using System;
using System.Linq;
using AiDotNet.Tensors.Engines;
using AiDotNet.Tensors.Engines.Autodiff;
using AiDotNet.Tensors.LinearAlgebra;
using Xunit;

namespace AiDotNet.Tensors.Tests.Engines;

/// <summary>torch.convolution (grouped, dilated, strided, transposed, 1-3 spatial axes) against PyTorch float64.</summary>
[Collection("EngineCurrentGlobalState")]
public class TorchConvolutionOpsTests
{
    private readonly CpuEngine _engine = new CpuEngine();

    // ((i * mul mod m) - shift) * scale, the same deterministic fill the torch reference used.
    private static Tensor<double> W(int[] shape, int mod, int mul, int shift, double scale = 0.1)
        => new Tensor<double>(Enumerable.Range(0, shape.Aggregate(1, (a, b) => a * b)).Select(i => (i * mul % mod - shift) * scale).ToArray(), shape);

    private static void Close(double[] expected, Tensor<double> actual, string what, double tolerance = 1e-12)
    {
        Assert.Equal(expected.Length, actual.Length);
        for (int i = 0; i < expected.Length; i++)
            Assert.True(Math.Abs(expected[i] - actual.GetFlat(i)) <= tolerance * Math.Max(1, Math.Abs(expected[i])),
                $"{what}[{i}]: torch {expected[i]:R}, ours {actual.GetFlat(i):R}");
    }

    [Fact]
    public void GroupedDilated1d_MatchesTorch()
    {
        var x = W(new[] { 2, 4, 9 }, 23, 7, 11);
        var w = W(new[] { 6, 2, 3 }, 19, 5, 9);
        var b = W(new[] { 6 }, 7, 3, 3);
        using var tape = new GradientTape<double>();
        var y = _engine.TensorConvolution(x, w, b, new[] { 2 }, new[] { 1 }, new[] { 2 }, false, new[] { 0 }, 2);
        Assert.Equal(new[] { 2, 6, 4 }, y.Shape.ToArray());
        Close(new[] { 0.64, -1.1, -0.9500000000000002, -1.09, -0.9600000000000002, 0.4700000000000001, 1.32, -0.16999999999999998, 1.2400000000000002, -0.6199999999999999, -0.020000000000000018, -0.58, 0.050000000000000155, -0.08000000000000007, 1.1900000000000002, -1.04, -0.06000000000000005, -0.55, 0.6000000000000001, 0.22999999999999998, -0.1100000000000001, -0.39, 0.6400000000000001, -1.29, 0.78, -0.9300000000000003, -0.78, -0.9400000000000002, -1.0700000000000003, 0.3600000000000002, 1.2100000000000002, -0.2700000000000001, 1.2600000000000002, -0.63, -0.030000000000000027, -0.55, 0.19999999999999996, -0.9100000000000001, -0.79, 0.0799999999999999, -0.1600000000000001, 1.06, 1.0599999999999998, -0.3600000000000001, -0.08000000000000002, -0.71, -0.8300000000000003, 0.4000000000000002 }, y, "grouped dilated 1-D");
        var loss = _engine.ReduceSum(_engine.TensorMultiply(y, W(y.Shape.ToArray(), 13, 4, 6)), null, false);
        var grads = tape.ComputeGradients(loss, new[] { x, w, b });
        Close(new[] { 0.0, -0.010000000000000037, 0.0, 0.4800000000000001, 0.0, -0.17000000000000004, 0.0, -1.04, 0.0, 0.0, 0.6100000000000001, 0.0, -0.49999999999999994, 0.0, 0.7300000000000001, 0.0, -0.21000000000000002, 0.0, 0.0, -0.12000000000000002, 0.0, 1.0100000000000002, 0.0, -0.4600000000000001, 0.0, 0.33000000000000007, 0.0, 0.0, -0.15000000000000002, 0.0, -0.09000000000000008, 0.0, 0.08000000000000007, 0.0, -0.43999999999999995, 0.0, 0.0, 0.22, 0.0, 0.8700000000000003, 0.0, -0.56, 0.0, 0.26, 0.0, 0.0, -0.41000000000000003, 0.0, 0.029999999999999943, 0.0, 1.0000000000000002, 0.0, -0.06999999999999998, 0.0, 0.0, 0.6400000000000001, 0.0, -0.47000000000000014, 0.0, 0.009999999999999981, 0.0, 0.8200000000000003, 0.0, 0.0, -0.12, 0.0, 0.08999999999999997, 0.0, -0.26, 0.0, -0.1600000000000001, 0.0 }, grads[x], "grouped dilated 1-D dx");
        Close(new[] { -0.35000000000000014, 0.08000000000000002, -0.33, -0.41000000000000014, 1.3600000000000003, -0.6500000000000001, -0.15000000000000008, 0.9400000000000002, -0.24, -0.5100000000000002, -0.04999999999999993, -0.2600000000000002, -0.47000000000000003, -0.54, 0.8900000000000001, -0.35000000000000003, -0.02999999999999997, -0.25999999999999995, -1.4100000000000004, 0.55, 0.6400000000000001, -0.35000000000000003, 0.8100000000000002, -0.2600000000000002, -1.1700000000000004, 0.9400000000000002, 0.6400000000000001, -0.5000000000000002, 0.45000000000000007, -0.6500000000000001, 0.8900000000000001, -1.4000000000000001, 0.6400000000000001, -0.26000000000000006, -0.29999999999999993, 0.52 }, grads[w], "grouped dilated 1-D dw");
        Close(new[] { -0.6000000000000001, 0.4999999999999999, 0.30000000000000004, -1.2, 1.2000000000000002, -0.30000000000000004 }, grads[b], "grouped dilated 1-D db");
    }

